let measurement = "manualInput";
let uid = global.get('uid');

function addDailyData(device, value, day, dailyAmount){
    let record = {
        "measurement": measurement,
        "timestamp": day.toISOString(),
        "tags":{
            "UID": uid,
            "device": device,
            "fuel": value.fuel,
            "unit": value.unit,
        },
        "fields": {
            "amount": dailyAmount,
        }
    };
    return record;
}

let startDate = new Date(msg.payload.start);
let endDate = new Date(msg.payload.end);

let totalDays = 1 + Math.ceil((endDate - startDate) / (1000 * 60 * 60 * 24)); // Berechnen der Gesamtzahl der Tage
let dailyAmount = parseFloat(msg.payload.amount) / totalDays; // Täglicher Betrag

let data = [];

// Erstellen Sie einen Eintrag für jeden Tag zwischen Start- und Enddatum
for (let day = startDate; day <= endDate; day.setDate(day.getDate() + 1)) {
    data.push(addDailyData("manualInput", msg.payload, new Date(day), dailyAmount));
}

msg.payload = data;
flow.set("DataCache", data)

return msg;

let measurement = "manualInput";
let tagValue = global.get('uid');
let tagFuel = msg.payload.fuel;

let startDate = new Date(msg.payload.start);
let endDate = new Date(msg.payload.end);

// Setze die Zeit auf 23:59:59, um das Ende des Tages zu repräsentieren
endDate.setHours(23, 59, 59);

let fluxQuery = `from(bucket: "bananapi")
  |> range(start: ${startDate.toISOString()}, stop: ${endDate.toISOString()})
  |> filter(fn: (r) => r["_measurement"] == "${measurement}")
  |> filter(fn: (r) => r["tags_UID"] == "${tagValue}")
  |> filter(fn: (r) => r["tags_fuel"] == "${tagFuel}")`;

msg.query = fluxQuery;
return msg;

// Zugriff auf DataCache
let cache = flow.get('DataCache') || [];
let overlappingDates = [];

// Durchlaufen des msg.payload-Arrays
for(let item of msg.payload) {
    // Konvertieren Sie _time in ein Date-Objekt und zurück in einen ISO8601-String mit Millisekunden
    let itemTimeWithMillis = new Date(item._time).toISOString();
    // Überprüfen, ob der aktuelle Timestamp bereits im Cache existiert
    for(let cItem of cache){
        if(cItem.timestamp == itemTimeWithMillis) {
            // Füge das Datum zur Liste der überlappenden Daten hinzu
            overlappingDates.push(itemTimeWithMillis);
        }
    }
}

if(overlappingDates.length > 0) {
    // Überlappungen gefunden - sende Fehler
    msg.payload = {
        error: "Es gibt zeitliche Überschneidungen",
        overlappingDates: overlappingDates
    };
    msg.statusCode = 400; // Setze den Statuscode auf 400 (Bad Request)
    return [msg, null];
}

// Keine Überlappungen gefunden - Daten weitergeben
msg.payload = cache;
return [null, msg];

